using System.Linq;using NUnit.Framework;using Rootborn.Game.Placement;using UnityEditor;using UnityEngine;using UnityEngine.Tilemaps;
namespace Rootborn.Tests.EditMode.Interiors{public sealed class WheatPlanterArtTests{
[TestCase("sprout")][TestCase("leaf")][TestCase("green")][TestCase("ripe")]public void OneCellPlanterHasDurableCrispSpriteAndRegisteredFurnitureTile(string slug){string stem="Activity31_wheat_planter_"+slug;string imagePath="Assets/Art/CareerFurniture/Activity31/"+stem+"_1x1.png";var sprite=AssetDatabase.LoadAssetAtPath<Sprite>(imagePath);Assert.That(sprite,Is.Not.Null,"Reviewed Comfy export must be imported before catalogue registration");Assert.That(sprite.rect.size,Is.EqualTo(new Vector2(48,96)));Assert.That(sprite.pivot,Is.EqualTo(new Vector2(24,24)));Assert.That(sprite.pixelsPerUnit,Is.EqualTo(48));var importer=(TextureImporter)AssetImporter.GetAtPath(imagePath);Assert.That(importer.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(importer.mipmapEnabled,Is.False);Assert.That(importer.npotScale,Is.EqualTo(TextureImporterNPOTScale.None));Assert.That(importer.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));var furniture=AssetDatabase.LoadAssetAtPath<FurnitureDefinition>("Assets/Data/Interiors/Furniture/Activity31/Furniture_"+stem+".asset");Assert.That(furniture,Is.Not.Null);Assert.That(furniture.StableId,Is.EqualTo("activity31.wheat.planter."+slug));Assert.That(furniture.DisplayName,Does.Contain("밀 화분"));Assert.That(furniture.FootprintCells,Is.EquivalentTo(new[]{Vector2Int.zero}));Assert.That(furniture.AllowedSurfaceIds,Does.Contain("house"));Assert.That(furniture.BlocksMovement,Is.True);Assert.That(furniture.TileParts.Count,Is.EqualTo(1));Assert.That(((Tile)furniture.TileParts[0].Tile).sprite,Is.SameAs(sprite));var settings=UnityEditor.AddressableAssets.AddressableAssetSettingsDefaultObject.Settings;foreach(var path in new[]{imagePath,AssetDatabase.GetAssetPath(furniture),AssetDatabase.GetAssetPath(furniture.TileParts[0].Tile)})Assert.That(settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path)),Is.Not.Null,"Actual sprite,definition and tile require stable independent addresses");var registry=AssetDatabase.LoadAssetAtPath<Rootborn.Game.Common.GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset");Assert.That(registry.FurnitureDefinitions.Any(f=>f==furniture),Is.True);}
}}
